use phonebook_rt as rt;
use std::collections::BTreeMap;

/// 000-0000001  IS_ADULT
///
/// A local extension: this is custom logic, not a registered address.
fn is_adult(row: &BTreeMap<String, String>) -> bool {
    let row: BTreeMap<String, String> = row.clone();
    let cell: String = rt::collections_::get(&row, &"age".to_string(), &"".to_string());
    let age: i64 = rt::numbers_::parse_int(&cell, &-1);
    let adult: bool = (age > 17);
    adult
}

/// 000-0000002  NAME_OF
///
/// A local extension: this is custom logic, not a registered address.
fn name_of(row: &BTreeMap<String, String>) -> String {
    let row: BTreeMap<String, String> = row.clone();
    let name: String = rt::collections_::get(&row, &"name".to_string(), &"?".to_string());
    name
}

fn main() {
    let rows: Vec<BTreeMap<String, String>> = rt::io_::read_csv(&"examples/data/people.csv".to_string());
    let adults: Vec<BTreeMap<String, String>> = rows.iter().cloned().filter(|_pb_x| is_adult(_pb_x)).collect::<Vec<_>>();
    let names: Vec<String> = adults.iter().map(|_pb_x| name_of(_pb_x)).collect::<Vec<_>>();
    let ordered: Vec<String> = rt::collections_::sort_seq(&names);
    rt::core::print_lines(&ordered);
}
